        elif direction == 's':
            new_player_row += 1
        elif direction == 'a':
            new_player_col -= 1
        elif direction == 'd':
            new_player_col += 1

        # Boundary check to prevent IndexError
        if not (0 <= new_player_row < len(self.map) and 0 <= new_player_col < len(self.map[0])):
            return self.check_win()

        if self.map[new_player_row][new_player_col] != '#':
            if (new_player_row, new_player_col) in self.boxes:
                # Calculate the position where the box would be pushed
                new_box_row = new_player_row + (new_player_row - self.player_row)
                new_box_col = new_player_col + (new_player_col - self.player_col)

                # Check boundaries for the box
                if not (0 <= new_box_row < len(self.map) and 0 <= new_box_col < len(self.map[0])):
                    return self.check_win()

                # Box can be pushed if the target cell is not a wall and not another box
