            return self.get_my_cards()

        # Count occurrences of digits in the expression
        statistic = {}
        for c in expression:
            if c.isdigit():
                statistic[c] = statistic.get(c, 0) + 1

        # Verify that the expression uses exactly the numbers provided in self.nums
        nums_copy = self.nums[:]
        try:
            for num in nums_copy:
                s_num = str(num)
                if statistic.get(s_num, 0) > 0:
                    statistic[s_num] -= 1
                else:
                    return False

            # Ensure no extra digits were used
            if any(count > 0 for count in statistic.values()):
                return False

            return self.evaluate_expression(expression)
