        elif len(parts) > 0 and parts[0].endswith(".py"):
            parts = parts[1:]

        i = 0
        while i < len(parts):
            token = parts[i]
            if token.startswith("-"):
                # Clean the key (remove leading dashes)
                key = token.lstrip("-")

                if "=" in key:
                    # Handle --arg=value
                    key, value = key.split("=", 1)
                    self.arguments[key] = self._convert_type(key, value)
                else:
                    # Check if next token is a value or if this is a boolean flag
                    if i + 1 < len(parts) and not parts[i+1].startswith("-"):
                        value = parts[i+1]
                        self.arguments[key] = self._convert_type(key, value)
                        i += 1  # Consume value
                    else:
                        # It's a boolean flag
                        self.arguments[key] = True
            i += 1

        missing_args = self.required - set(self.arguments.keys())
        if missing_args:
            return (False, missing_args)
        return (True, None)

    def get_argument(self, key):
        """
        Retrieves the value of the specified argument from the arguments dictionary and returns it.
        """
        return self.arguments.get(key, None)

    def add_argument(self, arg, required=False, arg_type=str):
        """
        Adds an argument to self.types and self.required.
        """
        self.types[arg] = arg_type
        if required:
            self.required.add(arg)

    def _convert_type(self, arg, value):
        """
        Try to convert the type of input value by searching in self.types.
        """
        if arg not in self.types:
            return value

        target_type = self.types[arg]
        try:
            # Handle cases where target_type might be a string like 'int' instead of the type object int
            if target_type == 'int':
                return int(value)
            if target_type == 'float':
                return float(value)
            if target_type == 'bool':
                return value.lower() in ('true', '1', 't', 'y', 'yes')

            # If it's a callable type (like int, float, etc)
            if callable(target_type):
                return target_type(value)
        except (ValueError, TypeError):
            pass

        return value
