class Calculator:
    """
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    """

    def __init__(self):
        """
        Initialize the operations performed by the five operators'+','-','*','/','^'
        """
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y
        }

    def calculate(self, expression):
        """
        Calculate the value of a given expression
        :param expression: string, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        """
        operand_stack = []
        operator_stack = []
        num_buffer = ''

        try:
            for char in expression:
                if char.isdigit() or char == '.':
                    num_buffer += char
                else:
                    if num_buffer:
                        operand_stack.append(float(num_buffer))
                        num_buffer = ''

                    if char in self.operators:
                        while (operator_stack and operator_stack[-1] != '(' and 
                               self.precedence(operator_stack[-1]) >= self.precedence(char)):
                            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                        operator_stack.append(char)
                    elif char == '(':
                        operator_stack.append(char)
                    elif char == ')':
                        while operator_stack and operator_stack[-1] != '(':
                            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                        if operator_stack and operator_stack[-1] == '(':
                            operator_stack.pop()

            if num_buffer:
                operand_stack.append(float(num_buffer))

            while operator_stack:
                operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)

            return operand_stack[-1] if operand_stack else None
        except Exception:
            return None

    def precedence(self, operator):
        """
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment. 
        The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: string, given operator
        :return: int, the priority of the given operator, otherwise return 0
        """
        precedences = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
        return precedences.get(operator, 0)

    def apply_operator(self, operand_stack, operator_stack):
        """
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operand stack, and store the results at the top of the operand stack
        :param operand_stack:list
        :param operator_stack:list
        :return: the updated operand_stack and operator_stack
        """
        if len(operand_stack) < 2 or not operator_stack:
            return operand_stack, operator_stack

        operator = operator_stack.pop()
        operand2 = operand_stack.pop()
        operand1 = operand_stack.pop()

        result = self.operators[operator](operand1, operand2)
        operand_stack.append(result)

        return operand_stack, operator_stack

from collections import Counter

class DataStatistics:
    """
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    """

    def mean(self, data):
        """
        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:list, data list
        :return:float, the mean value
        """
        if not data:
            return 0.0
        return round(sum(data) / len(data), 2)

    def median(self, data):
        """
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:list, data list
        :return:float, the median value
        """
        if not data:
            return 0.0
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n % 2 == 0:
            middle = n // 2
            # Average of the two middle elements
            return round((sorted_data[middle - 1] + sorted_data[middle]) / 2, 2)
        else:
            middle = n // 2
            return float(round(sorted_data[middle], 2))

    def mode(self, data):
        """
        Calculate the mode of a set of data
        :param data:list, data list
        :return:list, the mode
        """
        if not data:
            return []
        counter = Counter(data)
        mode_count = max(counter.values())
        mode = [x for x, count in counter.items() if count == mode_count]
        return sorted(mode)

