        total_val = 0

        for word in words:
            if word not in self.numwords:
                continue

            multiplier, value = self.numwords[word]

            if multiplier == 1:
                current_val += value
            elif multiplier == 100:
                current_val *= multiplier
            else:
                total_val += current_val * multiplier
                current_val = 0

        total_val += current_val
        return str(total_val)

